// src/context/AuthContext.js
import React, { createContext, useState, useEffect, useContext, useCallback, useMemo } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
    const [isLoggedIn, setIsLoggedIn] = useState(false);
    const [user, setUser] = useState(null); // ⭐ 핵심 변경: user 객체를 통째로 관리
    const [accessToken, setAccessToken] = useState(null);
    const [loadingAuth, setLoadingAuth] = useState(true); // 기본값을 true로 유지

    // logout 함수를 fetchUserInfo보다 먼저 선언
    const logout = useCallback(() => {
        localStorage.removeItem('accessToken');
        setIsLoggedIn(false);
        setUser(null); // 로그아웃 시 user 객체도 null로 설정
        setAccessToken(null);
        setLoadingAuth(false); // 로그아웃 시에는 바로 로딩 끝
        console.log('AuthContext: User logged out.');
    }, []);

    const fetchUserInfo = useCallback(async (token) => {
        if (!token) { // 토큰이 없으면 바로 로그아웃 처리
            console.log('AuthContext: fetchUserInfo - Token is null or undefined, logging out.');
            logout();
            return false;
        }
        try {
            const response = await axios.get('http://localhost:8080/api/auth/me', {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            const userData = response.data;
            console.log('AuthContext: fetchUserInfo - Full response data:', userData); // 전체 응답 데이터 로그
            
            // ⭐ 핵심 변경: user 객체 생성 및 상태 업데이트
            setUser({
                username: userData.username,
                memberNo: userData.memberNo,
                role: userData.role // 역할 정보는 role 속성으로
            });
            setIsLoggedIn(true);
            setAccessToken(token);
            console.log('AuthContext: fetchUserInfo - Fetched Role:', userData.role);
            console.log('AuthContext: fetchUserInfo - Fetched Username:', userData.username);
            return true;
        } catch (error) {
            console.error('AuthContext: fetchUserInfo - Error fetching user info:', error);
            logout(); // 에러 발생 시 로그아웃 처리
            return false;
        } finally {
            setLoadingAuth(false); // 정보 로딩이 끝나면 loadingAuth를 false로 설정
        }
    }, [logout]);

    useEffect(() => {
        const token = localStorage.getItem('accessToken');
        if (token) {
            console.log('AuthContext: Initial useEffect - Found token, fetching user info...');
            fetchUserInfo(token);
        } else {
            setIsLoggedIn(false);
            setLoadingAuth(false);
            console.log('AuthContext: Initial useEffect - No token, auth loading finished.');
        }
    }, [fetchUserInfo]);

    const hasAdminPermission = useCallback(() => {
        // user 객체가 존재하고 role이 ADMIN인 경우 확인
        const isAdmin = user && (user.role === 'CONTENT_ADMIN' || user.role === 'SYSTEM_ADMIN');
        console.log('AuthContext: hasAdminPermission called - Current user:', user); // user 객체 전체 로그
        console.log('AuthContext: hasAdminPermission result:', isAdmin);
        return isAdmin;
    }, [user]); // ⭐ 핵심 변경: user 객체 전체를 의존성으로

    const contextValue = useMemo(() => ({
        isLoggedIn,
        user, // ⭐ 핵심 변경: user 객체 전체를 전달하도록 변경
        accessToken,
        loading: loadingAuth, // ⭐ 핵심 변경: loadingAuth를 loading으로 이름 변경하여 전달
        login: async (username, password) => {
            setLoadingAuth(true); // 로그인 시작 시 로딩 시작
            try {
                const response = await axios.post(`${process.env.REACT_APP_BACKEND_BASE_URL}/api/auth/login`, {
                    loginId: username, // 백엔드 필드명에 맞게
                    password: password
                });
                const { accessToken } = response.data;
                localStorage.setItem('accessToken', accessToken);
                await fetchUserInfo(accessToken); // 로그인 성공 후 사용자 정보 가져오기
                return true;
            } catch (error) {
                console.error('AuthContext: Login failed:', error);
                setLoadingAuth(false); // 로그인 실패 시 로딩 끝
                if (error.response && error.response.data && error.response.data.message) {
                    throw new Error(error.response.data.message);
                } else {
                    throw new Error('로그인 실패: 서버 응답 없음 또는 네트워크 오류');
                }
            }
        },
        logout,
        hasAdminPermission
    }), [isLoggedIn, user, accessToken, loadingAuth, fetchUserInfo, logout, hasAdminPermission]); // user, loadingAuth 의존성 추가

    // AuthContext 내부에서 loadingAuth가 true일 때 렌더링하는 부분은 제거 (최상위 컴포넌트에서 처리)
    // if (loadingAuth) {
    //     return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', fontSize: '24px', fontWeight: 'bold' }}>인증 정보 로딩 중... ⏳</div>;
    // }

    return (
        <AuthContext.Provider value={contextValue}>
            {children}
        </AuthContext.Provider>
    );
};

// useAuth 훅도 AuthContext에서 가져와서 사용
export const useAuth = () => useContext(AuthContext);
